// Fetches a synthetic portrait for each member of the teaching team.
//
//   node scripts/fetch-portraits.mjs
//
// A one-off authoring tool, NOT part of the build. It is the only thing in
// this repo that touches the network, and it runs when a person is added, not
// when the site is built: CLAUDE.md says everything ships in the build, and a
// remote image is a way for the deployed site to be broken while the local one
// looks fine. The files it writes are committed.
//
// The faces are generated by a GAN at thispersondoesnotexist.com and depict
// nobody. That is the point, and it is also why the people page says so in
// writing: a photograph is the one thing on a course site a reader believes
// without checking, so the site has to be the one telling them.
import { existsSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import sharp from "sharp";

const SOURCE = "https://thispersondoesnotexist.com/random-person.jpeg";
const SIZE = 800;

// Slugs must match the person entries in src/content/people/.
const people = ["tessa-varga", "amos-redfern", "priya-raghunathan", "marta-ilves"];

const force = process.argv.includes("--force");
// Named slugs replace only those. The generator hands out a random face and
// some of them are children or heavily artefacted, so refetching one person
// without disturbing the other three is the normal case, not an edge case.
const only = process.argv.slice(2).filter((arg) => !arg.startsWith("--"));
const wanted = only.length > 0 ? only : people;

for (const slug of wanted) {
  const out = resolve(`src/content/people/${slug}.avif`);
  if (existsSync(out) && !force && only.length === 0) {
    console.log(`skip  ${slug} (already there; pass --force to replace)`);
    continue;
  }

  const response = await fetch(SOURCE, {
    headers: {
      // The endpoint serves an HTML page to a bare client and the image only
      // to something that looks like a browser.
      "User-Agent":
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/131.0 Safari/537.36",
      Referer: "https://thispersondoesnotexist.com/",
      Accept: "image/jpeg,image/*",
    },
  });
  if (!response.ok) throw new Error(`${slug}: ${response.status} ${response.statusText}`);

  const type = response.headers.get("content-type") ?? "";
  if (!type.startsWith("image/")) {
    throw new Error(`${slug}: expected an image, got ${type}`);
  }

  const source = Buffer.from(await response.arrayBuffer());
  const avif = await sharp(source)
    .resize(SIZE, SIZE, { fit: "cover", position: "attention" })
    .avif({ quality: 62 })
    .toBuffer();

  writeFileSync(out, avif);
  console.log(`wrote src/content/people/${slug}.avif (${SIZE}x${SIZE}, ${avif.length} bytes)`);

  // The endpoint hands out one face per request and it is somebody else's
  // server. Four requests, spaced.
  await new Promise((done) => setTimeout(done, 1200));
}
